it('wraps an undefined rejection for onError while preserving its cause and caller value', async () => {
  const {outcome, observed} = await runTurnWithRejection(undefined);

  expect({
    isError: observed instanceof Error,
    message: observed?.message,
    hasCause: observed ? Object.hasOwn(observed, 'cause') : false,
    cause: observed?.cause,
